const input=$json.body??$json;
const outcome=String(input.outcome??input.signature_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const sellerId=input.seller_id??input.seller_contact_id;
const buyerId=input.buyer_id??input.assignee_id;
const contractPrice=Number(input.contract_price??0);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const closingDate=String(input.closing_date??'').trim();
const executedAt=String(input.executed_at??input.signature_executed_at??'').trim();
const agreementType=String(input.agreement_type??'purchase_agreement').trim();
const dnc=input.dnc===true||outcome==='blocked_dnc';
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const identityReady=Boolean(dealId&&leadId&&propertyId);
const partiesReady=Boolean(sellerId&&buyerId);
const priceProtected=mao>0&&contractPrice>0&&contractPrice<=mao;
const closingDateValid=Boolean(closingDate);
let status='needs_review',next='WF-126',reason='transaction readiness requires review';
if(dnc){status='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(blockers.length){status='blocked';next='WF-126';reason='active blockers';}
else if(outcome!=='executed'&&input.signature_executed!==true){status='signature_not_executed';next='WF-322';reason='executed signature evidence not confirmed';}
else if(!identityReady){status='incomplete_identity';next='WF-126';reason='deal/lead/property identity missing';}
else if(!partiesReady){status='buyer_seller_missing';next='WF-126';reason='seller/buyer transaction parties incomplete';}
else if(!priceProtected){status='above_mao';next='WF-126';reason='contract price exceeds protected dynamic MAO';}
else if(!closingDateValid){status='closing_date_required';next='WF-126';reason='closing date is required before transaction launch';}
else if(!executedAt){status='execution_timestamp_required';next='WF-322';reason='executed signature timestamp missing';}
else{status='transaction_ready';next='WF-324';reason='executed agreement validated and ready for closing coordination';}
return [{json:{...input,workflow_id:'WF-323',workflow_name:'Executed Signature → Transaction Readiness & Closing Launch Controller',status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,seller_id:sellerId||null,buyer_id:buyerId||null,contract_price:contractPrice,dynamic_mao:mao,price_protected:priceProtected,agreement_type:agreementType,closing_date:closingDate||null,executed_at:executedAt||null,next_workflow:next,human_review_required:status!=='transaction_ready',crm_activity:{activity_type:'transaction_readiness',deal_id:dealId,lead_id:leadId,property_id:propertyId,status,contract_price:contractPrice,closing_date:closingDate||null,agreement_type:agreementType,reason}}}];
